-- =====================================================================
-- Schedemy: estrutura do banco para PostgreSQL (Supabase)
--
-- Conversão do db/dump_schedemy.sql (MySQL):
--   - AUTO_INCREMENT          -> GENERATED BY DEFAULT AS IDENTITY
--   - ENUM(...)               -> VARCHAR + CHECK com os valores permitidos
--   - TINYINT(1)              -> BOOLEAN
--   - DATETIME                -> TIMESTAMP
--   - ON UPDATE CURRENT_TIMESTAMP -> gatilho atualizar_atualizado_em()
--
-- Rode no SQL Editor do Supabase. Apaga as tabelas do Schedemy se já existirem.
-- Depois rode db/supabase_dados.sql para carregar os dados iniciais.
-- =====================================================================

DROP TABLE IF EXISTS
  solicitacao_edicao_participante, solicitacao_edicao_anexo, solicitacao_edicao,
  sugestao_remarcacao, sala_virtual, registro_motivo, notificacao, log_auditoria,
  evento_externo, convidado_favorito, bloqueio_periodo, avaliacao_reuniao,
  agendamento_participante, agendamento_anexo, agendamento, disponibilidade,
  duracao_reuniao, usuario
CASCADE;

-- Mantém atualizado_em em dia a cada UPDATE (equivalente ao ON UPDATE do MySQL).
CREATE OR REPLACE FUNCTION atualizar_atualizado_em() RETURNS trigger AS $$
BEGIN
  NEW.atualizado_em := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Tabela unificada para cadastro de usuários
CREATE TABLE usuario (
  id_usuario         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_microsoft       VARCHAR(255) NOT NULL,
  nome               VARCHAR(150) NOT NULL,
  email              VARCHAR(150) NOT NULL,
  senha              VARCHAR(255) NOT NULL,
  telefone_whatsapp  VARCHAR(20),
  tipo_usuario       VARCHAR(20)  NOT NULL
    CONSTRAINT chk_usuario_tipo CHECK (tipo_usuario IN ('ADMIN','ALUNO','PROFESSOR','COORDENADOR','RECEPCIONISTA')),
  matricula_ra       VARCHAR(30),
  num_identificacao  VARCHAR(30),
  departamento       VARCHAR(100),
  ativo              BOOLEAN      NOT NULL DEFAULT TRUE,
  criado_em          TIMESTAMP    NOT NULL DEFAULT now(),
  atualizado_em      TIMESTAMP    NOT NULL DEFAULT now(),
  CONSTRAINT uk_usuario_id_microsoft UNIQUE (id_microsoft),
  CONSTRAINT uk_usuario_email UNIQUE (email)
);
CREATE INDEX idx_usuario_tipo ON usuario (tipo_usuario);
CREATE INDEX idx_usuario_matricula_ra ON usuario (matricula_ra);
CREATE TRIGGER trg_usuario_atualizado_em BEFORE UPDATE ON usuario
  FOR EACH ROW EXECUTE FUNCTION atualizar_atualizado_em();

-- Durações de reunião disponibilizadas pelo sistema
CREATE TABLE duracao_reuniao (
  id_duracao  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  minutos     INTEGER NOT NULL
    CONSTRAINT chk_duracao_minutos CHECK (minutos IN (10,15,20,30,45,60)),
  ativo       BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT uk_duracao_minutos UNIQUE (minutos)
);

-- Grade semanal de horários de atendimento de professores/coordenadores
CREATE TABLE disponibilidade (
  id_disponibilidade  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario          BIGINT    NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  dia_semana          INTEGER   NOT NULL
    CONSTRAINT chk_disponibilidade_dia CHECK (dia_semana BETWEEN 1 AND 7),
  horario_inicio      TIME      NOT NULL,
  horario_fim         TIME      NOT NULL,
  ativo               BOOLEAN   NOT NULL DEFAULT TRUE,
  criado_em           TIMESTAMP NOT NULL DEFAULT now(),
  CONSTRAINT chk_disponibilidade_horario CHECK (horario_fim > horario_inicio)
);
CREATE INDEX idx_disponibilidade_busca ON disponibilidade (id_usuario, dia_semana, ativo);

-- Tabela principal de agendamentos e solicitações de reuniões
CREATE TABLE agendamento (
  id_agendamento         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario             BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  id_duracao             BIGINT       NOT NULL REFERENCES duracao_reuniao (id_duracao) ON UPDATE CASCADE,
  id_agendamento_origem  BIGINT       REFERENCES agendamento (id_agendamento) ON DELETE SET NULL ON UPDATE CASCADE,
  data_reuniao           DATE         NOT NULL,
  horario_inicio         TIME         NOT NULL,
  formato                VARCHAR(20)  NOT NULL
    CONSTRAINT chk_agendamento_formato CHECK (formato IN ('PRESENCIAL','ONLINE','HIBRIDO')),
  topico                 VARCHAR(200) NOT NULL,
  resumo                 VARCHAR(500),
  status_agend           VARCHAR(30)  NOT NULL DEFAULT 'PENDENTE'
    CONSTRAINT chk_agendamento_status CHECK (status_agend IN
      ('PENDENTE','CONFIRMADO','EM_ANDAMENTO','CONCLUIDO','CANCELADO','AGUARDANDO_RESPOSTA')),
  criado_em              TIMESTAMP    NOT NULL DEFAULT now(),
  atualizado_em          TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX idx_agendamento_duracao ON agendamento (id_duracao);
CREATE INDEX idx_agendamento_origem ON agendamento (id_agendamento_origem);
CREATE INDEX idx_agendamento_data_status ON agendamento (data_reuniao, status_agend);
CREATE INDEX idx_agendamento_usuario ON agendamento (id_usuario);
CREATE INDEX idx_agendamento_status ON agendamento (status_agend);
CREATE TRIGGER trg_agendamento_atualizado_em BEFORE UPDATE ON agendamento
  FOR EACH ROW EXECUTE FUNCTION atualizar_atualizado_em();

-- Arquivos anexados aos agendamentos
CREATE TABLE agendamento_anexo (
  id_agendamento_anexo  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento        BIGINT       NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  nome_arquivo          VARCHAR(255) NOT NULL,
  url_arquivo           VARCHAR(500) NOT NULL
);
CREATE INDEX idx_anexo_agendamento ON agendamento_anexo (id_agendamento);

-- Participantes de cada agendamento e seus status de resposta
CREATE TABLE agendamento_participante (
  id_agendamento   BIGINT      NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  id_usuario       BIGINT      NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  papel            VARCHAR(20) NOT NULL DEFAULT 'CONVIDADO'
    CONSTRAINT chk_participante_papel CHECK (papel IN ('ORGANIZADOR','CONVIDADO')),
  status_resposta  VARCHAR(20) NOT NULL DEFAULT 'PENDENTE'
    CONSTRAINT chk_participante_status CHECK (status_resposta IN ('PENDENTE','ACEITO','RECUSADO')),
  data_resposta    TIMESTAMP,
  PRIMARY KEY (id_agendamento, id_usuario)
);
CREATE INDEX idx_participante_usuario ON agendamento_participante (id_usuario);

-- Avaliações pós-atendimento registradas pelos alunos
CREATE TABLE avaliacao_reuniao (
  id_avaliacao    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento  BIGINT       NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  id_aluno        BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  nota            INTEGER      NOT NULL
    CONSTRAINT chk_avaliacao_nota CHECK (nota BETWEEN 0 AND 5),
  comentario      VARCHAR(200),
  criado_em       TIMESTAMP    NOT NULL DEFAULT now(),
  CONSTRAINT uk_avaliacao_aluno_agendamento UNIQUE (id_agendamento, id_aluno)
);
CREATE INDEX idx_avaliacao_aluno ON avaliacao_reuniao (id_aluno);

-- Períodos de indisponibilidade na agenda do docente
CREATE TABLE bloqueio_periodo (
  id_bloqueio            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario             BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  data_inicio            DATE         NOT NULL,
  data_fim               DATE         NOT NULL,
  horario_inicio         TIME,
  horario_fim            TIME,
  e_recorrente           BOOLEAN      NOT NULL DEFAULT FALSE,
  dia_semana_recorrente  INTEGER,
  motivo                 VARCHAR(255),
  sincronizado_outlook   BOOLEAN      NOT NULL DEFAULT FALSE,
  criado_em              TIMESTAMP    NOT NULL DEFAULT now(),
  CONSTRAINT chk_bloqueio_datas CHECK (data_fim >= data_inicio),
  CONSTRAINT chk_bloqueio_recorrencia CHECK (
    (NOT e_recorrente AND dia_semana_recorrente IS NULL)
    OR (e_recorrente AND dia_semana_recorrente BETWEEN 1 AND 7))
);
CREATE INDEX idx_bloqueio_consulta ON bloqueio_periodo (id_usuario, data_inicio, data_fim);

-- Professores/coordenadores favoritados por alunos
CREATE TABLE convidado_favorito (
  id_convidado_favorito  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_aluno               BIGINT    NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  id_favorito            BIGINT    NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  criado_em              TIMESTAMP NOT NULL DEFAULT now(),
  CONSTRAINT uk_favorito_aluno_usuario UNIQUE (id_aluno, id_favorito)
);
CREATE INDEX idx_favorito_usuario ON convidado_favorito (id_favorito);

-- Eventos de calendários externos sincronizados com o sistema
CREATE TABLE evento_externo (
  id_evento_externo     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario            BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  id_agendamento        BIGINT       REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  provedor              VARCHAR(50)  NOT NULL,
  id_evento_provedor    VARCHAR(255) NOT NULL,
  tipo_evento           VARCHAR(50)  NOT NULL,
  ultima_sincronizacao  TIMESTAMP,
  CONSTRAINT uk_evento_externo_outlook UNIQUE (provedor, id_evento_provedor)
);
CREATE INDEX idx_evento_externo_usuario ON evento_externo (id_usuario);
CREATE INDEX idx_evento_externo_agendamento ON evento_externo (id_agendamento);

-- Trilha auditável de operações (LGPD e RNF 19)
CREATE TABLE log_auditoria (
  id_log             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario         BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  acao               VARCHAR(100) NOT NULL,
  tabela_afetada     VARCHAR(50)  NOT NULL,
  id_tabela_afetada  BIGINT,
  detalhes           VARCHAR(200),
  ip_origem          VARCHAR(45),
  criado_em          TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX idx_log_usuario_data ON log_auditoria (id_usuario, criado_em);
CREATE INDEX idx_log_tabela_registro ON log_auditoria (tabela_afetada, id_tabela_afetada);

-- Fila e histórico de notificações
CREATE TABLE notificacao (
  id_notificacao  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario      BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
  id_agendamento  BIGINT       REFERENCES agendamento (id_agendamento) ON UPDATE CASCADE,
  canal_envio     VARCHAR(20)  NOT NULL DEFAULT 'EMAIL'
    CONSTRAINT chk_notificacao_canal CHECK (canal_envio IN ('EMAIL','SISTEMA','WHATSAPP')),
  tipo_evento     VARCHAR(50)  NOT NULL,
  mensagem        VARCHAR(200) NOT NULL,
  status_envio    VARCHAR(20)  NOT NULL DEFAULT 'PENDENTE'
    CONSTRAINT chk_notificacao_status CHECK (status_envio IN ('PENDENTE','ENVIADO','FALHA')),
  enviado_em      TIMESTAMP,
  criado_em       TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX idx_notificacao_agendamento ON notificacao (id_agendamento);
CREATE INDEX idx_notificacao_status ON notificacao (id_usuario, status_envio);

-- Justificativas de cancelamentos e alterações em reuniões
CREATE TABLE registro_motivo (
  id_registro_motivo  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento      BIGINT      NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  id_usuario          BIGINT      NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  tipo_operacao       VARCHAR(30) NOT NULL
    CONSTRAINT chk_motivo_tipo CHECK (tipo_operacao IN
      ('CANCELAMENTO','SOLICITACAO_EDICAO','RECUSA_AGENDAMENTO','RECUSA_REMARCACAO')),
  -- TEXT, como na entidade RegistroMotivo (columnDefinition = "TEXT").
  justificativa       TEXT        NOT NULL,
  criado_em           TIMESTAMP   NOT NULL DEFAULT now()
);
CREATE INDEX idx_motivo_agendamento ON registro_motivo (id_agendamento);
CREATE INDEX idx_motivo_usuario ON registro_motivo (id_usuario);

-- Salas virtuais do Microsoft Teams
CREATE TABLE sala_virtual (
  id_sala_virtual  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento   BIGINT        NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  link_teams       VARCHAR(1000) NOT NULL,
  criado_em        TIMESTAMP     NOT NULL DEFAULT now(),
  CONSTRAINT uk_sala_agendamento UNIQUE (id_agendamento)
);

-- Solicitações de alteração de agendamentos
CREATE TABLE solicitacao_edicao (
  id_solicitacao       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento       BIGINT       NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  id_usuario           BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  id_nova_duracao      BIGINT       NOT NULL REFERENCES duracao_reuniao (id_duracao) ON UPDATE CASCADE,
  nova_data            DATE         NOT NULL,
  novo_horario_inicio  TIME         NOT NULL,
  novo_formato         VARCHAR(20)  NOT NULL
    CONSTRAINT chk_solicitacao_formato CHECK (novo_formato IN ('PRESENCIAL','ONLINE','HIBRIDO')),
  novo_topico          VARCHAR(200) NOT NULL,
  novo_resumo          VARCHAR(500),
  motivo               VARCHAR(200) NOT NULL,
  status_solicitacao   VARCHAR(20)  NOT NULL DEFAULT 'PENDENTE'
    CONSTRAINT chk_solicitacao_status CHECK (status_solicitacao IN ('PENDENTE','ACEITA','RECUSADA')),
  criado_em            TIMESTAMP    NOT NULL DEFAULT now(),
  respondido_em        TIMESTAMP
);
CREATE INDEX idx_solicitacao_usuario ON solicitacao_edicao (id_usuario);
CREATE INDEX idx_solicitacao_nova_duracao ON solicitacao_edicao (id_nova_duracao);
CREATE INDEX idx_solicitacao_agendamento ON solicitacao_edicao (id_agendamento);

-- Arquivos anexados às solicitações de edição
CREATE TABLE solicitacao_edicao_anexo (
  id_solicitacao_anexo  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_solicitacao        BIGINT       NOT NULL REFERENCES solicitacao_edicao (id_solicitacao) ON DELETE CASCADE ON UPDATE CASCADE,
  nome_arquivo          VARCHAR(255) NOT NULL,
  url_arquivo           VARCHAR(500) NOT NULL
);
CREATE INDEX idx_solicitacao_anexo ON solicitacao_edicao_anexo (id_solicitacao);

-- Participantes propostos em cada solicitação de edição
CREATE TABLE solicitacao_edicao_participante (
  id_solicitacao  BIGINT NOT NULL REFERENCES solicitacao_edicao (id_solicitacao) ON DELETE CASCADE ON UPDATE CASCADE,
  id_usuario      BIGINT NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  PRIMARY KEY (id_solicitacao, id_usuario)
);
CREATE INDEX idx_solicitacao_participante_usuario ON solicitacao_edicao_participante (id_usuario);

-- Propostas de reagendamento enviadas por professores
CREATE TABLE sugestao_remarcacao (
  id_sugestao          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_agendamento       BIGINT       NOT NULL REFERENCES agendamento (id_agendamento) ON DELETE CASCADE ON UPDATE CASCADE,
  id_usuario           BIGINT       NOT NULL REFERENCES usuario (id_usuario) ON UPDATE CASCADE,
  nova_data            DATE         NOT NULL,
  novo_horario_inicio  TIME         NOT NULL,
  motivo               VARCHAR(200) NOT NULL,
  status_remarcacao    VARCHAR(20)  NOT NULL DEFAULT 'PENDENTE'
    CONSTRAINT chk_sugestao_status CHECK (status_remarcacao IN ('PENDENTE','ACEITO','RECUSADO')),
  criado_em            TIMESTAMP    NOT NULL DEFAULT now(),
  respondido_em        TIMESTAMP
);
CREATE INDEX idx_sugestao_agendamento ON sugestao_remarcacao (id_agendamento);
CREATE INDEX idx_sugestao_usuario ON sugestao_remarcacao (id_usuario);
